CREATE OR REPLACE FUNCTION tmp_decode_pg_loid_text(p_val text)
RETURNS text
LANGUAGE plpgsql
AS $fn$
BEGIN
    IF p_val IS NULL OR btrim(p_val) = '' OR p_val !~ '^[0-9]+$' THEN
        RETURN p_val;
    END IF;
    BEGIN
        RETURN convert_from(lo_get(p_val::oid), 'UTF8');
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
END;
$fn$;

UPDATE event_competition SET
    description = tmp_decode_pg_loid_text(description),
    judgment_criteria_json = tmp_decode_pg_loid_text(judgment_criteria_json),
    rules_markdown = tmp_decode_pg_loid_text(rules_markdown)
WHERE coalesce(description, '') ~ '^[0-9]+$'
   OR coalesce(judgment_criteria_json, '') ~ '^[0-9]+$'
   OR coalesce(rules_markdown, '') ~ '^[0-9]+$';

UPDATE event_competition_result SET
    prize_details = tmp_decode_pg_loid_text(prize_details),
    notes = tmp_decode_pg_loid_text(notes)
WHERE coalesce(prize_details, '') ~ '^[0-9]+$'
   OR coalesce(notes, '') ~ '^[0-9]+$';

UPDATE event_competition_settings SET
    eligibility_text = tmp_decode_pg_loid_text(eligibility_text)
WHERE coalesce(eligibility_text, '') ~ '^[0-9]+$';

UPDATE event_competition_day SET
    notes = tmp_decode_pg_loid_text(notes)
WHERE coalesce(notes, '') ~ '^[0-9]+$';

UPDATE event_competition_content_block SET
    body_markdown = coalesce(tmp_decode_pg_loid_text(body_markdown), '[]')
WHERE coalesce(body_markdown, '') ~ '^[0-9]+$';

DROP FUNCTION tmp_decode_pg_loid_text(text);
